```javascript
const bcrypt = require('bcrypt');

const password = 'mysecretpassword';
const saltRounds = 10;

bcrypt.hash(password, saltRounds, (err, hash) => {
    if (err) {
        console.error(err);
    } else {
        console.log(hash);
    }
});
```

To verify a password, you would use the following code:
```javascript
