const hashedPassword = '$2b$10$R1U/oW7QyBqPxFGcJQl5mO';

bcrypt.compare(password, hashedPassword, (err, result) => {
    if (err) {
        console.error(err);
    } else {
        console.log(result);
    }
});
```

